# Slayer Editor — destructive command guard.
# Generated by the app on every start; edits here are overwritten.
# Enabled while $SLAYER_GUARD_DIR/guard_enabled exists (Settings → Security).
# The message comes from $SLAYER_GUARD_DIR/blocked_message.
# so a language change applies without restarting the shell.
#
# Loaded by the terminal rcfile for the interactive terminal, and through BASH_ENV by every
# non-interactive bash started from it (`bash script.sh`, `./script.sh`, `bash -c`).

# Interactive prompt: the full, strict list.
__slayer_guard_interactive=(
  '(^|[^[:alnum:]_-])rm[[:space:]]+(-[[:alpha:]]*[rf])+.*[[:space:]]+(/|~|\.\.)'
  '(^|[^[:alnum:]_-])rm[[:space:]]+(-[[:alpha:]]*[rf])+[[:space:]]+(\*|\.)'
  '(^|[^[:alnum:]_-])rm[[:space:]]+.*[[:space:]]+/[[:space:]]*$'
  '(^|[^[:alnum:]_-])rm[[:space:]]+-(rf|fr)[[:space:]]'
  '(^|[^[:alnum:]_-])rm[[:space:]]+\*'
  '(^|[^[:alnum:]_-])mkfs\.'
  '(^|[^[:alnum:]_-])dd[[:space:]]+.*of=/dev/'
  ':>[[:space:]]*/'
  '>[[:space:]]*/dev/(sd|hd|vd|nvme|mmcblk|block|dm-|loop|mapper)'
  '>[[:space:]]*/etc/'
  '(^|[^[:alnum:]_-])chmod[[:space:]]+-R[[:space:]]+777[[:space:]]+/'
  '(^|[^[:alnum:]_-])chown[[:space:]]+-R[[:space:]].*[[:space:]]+/[[:space:]]*$'
  '(^|[^[:alnum:]_-])find[[:space:]]+/[[:space:]].*-delete'
  '(^|[^[:alnum:]_-])find[[:space:]]+/[[:space:]].*xargs[[:space:]]+rm'
  '(^|[^[:alnum:]_-])mv[[:space:]]+/[[:space:]]'
  '(^|[^[:alnum:]_-])wipefs'
)

# Scripts: only catastrophic commands. Scripts legitimately run `rm -rf /some/path`
# (build, install and package scripts), so the interactive list would break them.
__slayer_guard_script=(
  '(^|[^[:alnum:]_-])rm[[:space:]]+(-[[:alpha:]]+[[:space:]]+)*(/|/\*|~|~/|~/\*|\$HOME|\$HOME/|\$HOME/\*|\*|\.|\./|\./\*|\.\.|\.\./)([[:space:]]|$)'
  '(^|[^[:alnum:]_-])mkfs\.'
  '(^|[^[:alnum:]_-])dd[[:space:]]+.*of=/dev/(sd|hd|vd|nvme|mmcblk|block|dm-|loop|mapper)'
  '>[[:space:]]*/dev/(sd|hd|vd|nvme|mmcblk|block|dm-|loop|mapper)'
  '(^|[^[:alnum:]_-])chmod[[:space:]]+-R[[:space:]]+777[[:space:]]+/([[:space:]]|$)'
  '(^|[^[:alnum:]_-])chown[[:space:]]+-R[[:space:]].*[[:space:]]+/([[:space:]]|$)'
  '(^|[^[:alnum:]_-])find[[:space:]]+/[[:space:]].*-delete'
  '(^|[^[:alnum:]_-])mv[[:space:]]+/[[:space:]]'
  '(^|[^[:alnum:]_-])wipefs'
)

# One combined regex per mode: a single match per command keeps the hook cheap.
__slayer_guard_join() { local IFS='|'; printf '%s' "$*"; }
__slayer_guard_re_interactive="$(__slayer_guard_join "${__slayer_guard_interactive[@]}")"
__slayer_guard_re_script="$(__slayer_guard_join "${__slayer_guard_script[@]}")"

__slayer_guard() {
  # Cheap glob pre-filter first: bash recompiles the regex on every match, which
  # would make every command in a script loop hundreds of times slower.
  case $BASH_COMMAND in
    *rm*|*mkfs*|*dd*|*chmod*|*chown*|*find*|*mv*|*wipefs*|*'>'*/dev/[!n]*|*'>'*/etc/*|*':>'*) ;;
    *) return 0 ;;
  esac
  [ -f "$SLAYER_GUARD_DIR/guard_enabled" ] || return 0
  local re
  if [[ $- == *i* ]]; then
    # Only commands typed at the prompt, not the internals of functions
    # (bash-completion, user functions).
    [ "${#FUNCNAME[@]}" -gt 1 ] && return 0
    re=$__slayer_guard_re_interactive
  else
    # Package managers run many maintainer/lifecycle scripts; never interfere.
    [ -n "$DPKG_MAINTSCRIPT_NAME$DPKG_RUNNING_VERSION$npm_lifecycle_event" ] && return 0
    re=$__slayer_guard_re_script
  fi
  if [[ $BASH_COMMAND =~ $re ]]; then
    local msg='Destructive command blocked.'
    [ -r "$SLAYER_GUARD_DIR/blocked_message" ] && msg=$(<"$SLAYER_GUARD_DIR/blocked_message")
    printf '\033[1;31m%s\033[0m\n' "$msg" >&2
    [[ $- == *i* ]] && return 1
    # Script: abort it (from a subshell too) instead of letting it continue as
    # if the command had run.
    printf '\033[1;31m  -> %s\033[0m\n' "$BASH_COMMAND" >&2
    [ "$BASHPID" != "$$" ] && kill -TERM "$$" 2>/dev/null
    exit 126
  fi
  return 0
}

# Every bash started from here (scripts included) loads this guard too.
export BASH_ENV="$SLAYER_GUARD_DIR/guard.sh"

if [[ $- == *i* ]]; then
  # extdebug: a non-zero return from the DEBUG trap skips the command.
  shopt -s extdebug
else
  # Not extdebug here: set during startup it tries to load the bashdb debugger.
  # functrace makes functions, subshells and command substitutions inherit the trap.
  set -o functrace
fi
trap '__slayer_guard' DEBUG
